program_source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    col_bars = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    row_spans = []
    start = 0
    for bar in row_bars:
        row_spans.append((start, bar))
        start = bar + 1
    row_spans.append((start, h))
    col_spans = []
    start = 0
    for bar in col_bars:
        col_spans.append((start, bar))
        start = bar + 1
    col_spans.append((start, w))

    colors = []
    for r0, r1 in row_spans:
        vals = {grid[r][c] for r in range(r0, r1) for c in range(col_spans[0][0], col_spans[0][1]) if grid[r][c] != 0}
        colors.append(next(iter(vals)))
    palette = set(colors)
    template = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans[1:]:
            vals = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0 and grid[r][c] not in palette}
            if vals:
                template = next(iter(vals))
                break
        if template is not None:
            break
    shape = [[any(grid[r][c] == template for r in range(r0, r1) for c in range(c0, c1) if (r-r0, c-c0) == (i, j)) for j in range(col_spans[0][1]-col_spans[0][0])] for i in range(row_spans[0][1]-row_spans[0][0])]
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_spans):
        color = colors[ri]
        for c0, c1 in col_spans:
            for i, r in enumerate(range(r0, r1)):
                for j, c in enumerate(range(c0, c1)):
                    out[r][c] = color if shape[i][j] else 0
    return out
'''
